static
void kernel_adi(int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  DX = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DY = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DT = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 /  SCALAR_VAL(2.0);
  b = SCALAR_VAL(1.0)+mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = SCALAR_VAL(1.0)+mul2;
  f = d;

  const int N = _PB_N - 1;

  for (t=1; t<=_PB_TSTEPS; t++) {

    for (i=1; i<N; i++) {
      v[0][i] = SCALAR_VAL(1.0);
      p[i][0] = SCALAR_VAL(0.0);
      q[i][0] = v[0][i];

      j = 1;
      for (; j + 3 < N; j += 4) {
        p[i][j]     = -c / (a*p[i][j-1]+b);
        q[i][j]     = (-d*u[j][i-1]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*d)*u[j][i] - f*u[j][i+1]-a*q[i][j-1])/(a*p[i][j-1]+b);
        p[i][j+1]   = -c / (a*p[i][j]+b);
        q[i][j+1]   = (-d*u[j+1][i-1]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*d)*u[j+1][i] - f*u[j+1][i+1]-a*q[i][j])/(a*p[i][j]+b);
        p[i][j+2]   = -c / (a*p[i][j+1]+b);
        q[i][j+2]   = (-d*u[j+2][i-1]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*d)*u[j+2][i] - f*u[j+2][i+1]-a*q[i][j+1])/(a*p[i][j+1]+b);
        p[i][j+3]   = -c / (a*p[i][j+2]+b);
        q[i][j+3]   = (-d*u[j+3][i-1]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*d)*u[j+3][i] - f*u[j+3][i+1]-a*q[i][j+2])/(a*p[i][j+2]+b);
      }
      for (; j < N; j++) {
        p[i][j] = -c / (a*p[i][j-1]+b);
        q[i][j] = (-d*u[j][i-1]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*d)*u[j][i] - f*u[j][i+1]-a*q[i][j-1])/(a*p[i][j-1]+b);
      }

      v[N-1][i] = SCALAR_VAL(1.0);
      for (j=N-2; j>=1; j--) {
        v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
      }
    }

    for (i=1; i<N; i++) {
      u[i][0] = SCALAR_VAL(1.0);
      p[i][0] = SCALAR_VAL(0.0);
      q[i][0] = u[i][0];

      j = 1;
      for (; j + 3 < N; j += 4) {
        p[i][j]     = -f / (d*p[i][j-1]+e);
        q[i][j]     = (-a*v[i-1][j]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*a)*v[i][j] - c*v[i+1][j]-d*q[i][j-1])/(d*p[i][j-1]+e);
        p[i][j+1]   = -f / (d*p[i][j]+e);
        q[i][j+1]   = (-a*v[i-1][j+1]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*a)*v[i][j+1] - c*v[i+1][j+1]-d*q[i][j])/(d*p[i][j]+e);
        p[i][j+2]   = -f / (d*p[i][j+1]+e);
        q[i][j+2]   = (-a*v[i-1][j+2]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*a)*v[i][j+2] - c*v[i+1][j+2]-d*q[i][j+1])/(d*p[i][j+1]+e);
        p[i][j+3]   = -f / (d*p[i][j+2]+e);
        q[i][j+3]   = (-a*v[i-1][j+3]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*a)*v[i][j+3] - c*v[i+1][j+3]-d*q[i][j+2])/(d*p[i][j+2]+e);
      }
      for (; j < N; j++) {
        p[i][j] = -f / (d*p[i][j-1]+e);
        q[i][j] = (-a*v[i-1][j]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*a)*v[i][j] - c*v[i+1][j]-d*q[i][j-1])/(d*p[i][j-1]+e);
      }

      u[i][N-1] = SCALAR_VAL(1.0);
      for (j=N-2; j>=1; j--) {
        u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
      }
    }
  }
#pragma endscop
}

