static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

  for (i = 0; i < _PB_M; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);

      j = 0;
      for (; j < _PB_N; )
	{
	  size_t vl = __riscv_vsetvl_e64m1(static_cast<size_t>(_PB_N - j));
	  vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
	  vfloat64m1_t vtmp = __riscv_vfmv_v_f_f64m1(0.0, vl);
	  vfloat64m1_t vA = __riscv_vle64_v_f64m1(&A[i][j], vl);
	  vtmp = __riscv_vfadd_vv_f64m1(vtmp, __riscv_vfmul_vv_f64m1(vA, vx, vl), vl);
	  tmp[i] = __riscv_vfmv_f_s_f64m1_f64(vtmp);
	  j += static_cast<int>(vl);
	}

      j = 0;
      for (; j < _PB_N; )
	{
	  size_t vl = __riscv_vsetvl_e64m1(static_cast<size_t>(_PB_N - j));
	  vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[j], vl);
	  vfloat64m1_t vA = __riscv_vle64_v_f64m1(&A[i][j], vl);
	  vfloat64m1_t vtmp = __riscv_vfmv_v_f_f64m1(tmp[i], vl);
	  vy = __riscv_vfadd_vv_f64m1(vy, __riscv_vfmul_vv_f64m1(vA, vtmp, vl), vl);
	  __riscv_vse64_v_f64m1(&y[j], vy, vl);
	  j += static_cast<int>(vl);
	}
    }
#pragma endscop

}

