static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
   {
     int idx = 0;
     while (idx < k) {
       size_t vl = __riscv_vsetvl_e64m1((size_t)(k - idx));
       vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[idx], vl);
       vfloat64m1_t vr = __riscv_vle64_v_f64m1(&r[k - idx - (int)vl], vl);
       vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(vr, vy, vl);
       vfloat64m1_t vsum = __riscv_vfredosum_vs_f64m1_f64m1(vprod, __riscv_vfmv_v_f_f64m1(0.0, 1), vl);
       sum += __riscv_vfmv_f_s_f64m1_f64(vsum);
       idx += (int)vl;
     }
   }
#else
   for (i=0; i<k; i++) {
      sum += r[k-i-1]*y[i];
   }
#endif

   alpha = - (r[k] + sum)/beta;

#if defined(__riscv_vector)
   {
     int idx = 0;
     while (idx < k) {
       size_t vl = __riscv_vsetvl_e64m1((size_t)(k - idx));
       vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[idx], vl);
       vfloat64m1_t vz = __riscv_vle64_v_f64m1(&z[idx], vl);
       vfloat64m1_t valpha = __riscv_vfmv_v_f_f64m1(alpha, 1);
       vfloat64m1_t vrhs = __riscv_vle64_v_f64m1(&y[k - idx - (int)vl], vl);
       vfloat64m1_t vtmp = __riscv_vfmul_vv_f64m1(valpha, vrhs, vl);
       vz = __riscv_vfadd_vv_f64m1(vy, vtmp, vl);
       __riscv_vse64_v_f64m1(&z[idx], vz, vl);
       idx += (int)vl;
     }
   }
#else
   for (i=0; i<k; i++) {
      z[i] = y[i] + alpha*y[k-i-1];
   }
#endif

#if defined(__riscv_vector)
   {
     int idx = 0;
     while (idx < k) {
       size_t vl = __riscv_vsetvl_e64m1((size_t)(k - idx));
       vfloat64m1_t vz = __riscv_vle64_v_f64m1(&z[idx], vl);
       __riscv_vse64_v_f64m1(&y[idx], vz, vl);
       idx += (int)vl;
     }
   }
#else
   for (i=0; i<k; i++) {
     y[i] = z[i];
   }
#endif

   y[k] = alpha;
 }
#pragma endscop

}

