static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  const int ny = _PB_NY;
  const int nx = _PB_NX;
  const DATA_TYPE half = SCALAR_VAL(0.5);
  const DATA_TYPE seven = SCALAR_VAL(0.7);

  for(t = 0; t < _PB_TMAX; t++)
    {
      for (j = 0; j < ny; j++)
	ey[0][j] = _fict_[t];

      for (i = 1; i < nx; i++)
	{
	  j = 0;
	  for (; j + 7 < ny; j += 8)
	    {
	      ey[i][j]     = ey[i][j] - half * (hz[i][j] - hz[i - 1][j]);
	      ey[i][j + 1] = ey[i][j + 1] - half * (hz[i][j + 1] - hz[i - 1][j + 1]);
	      ey[i][j + 2] = ey[i][j + 2] - half * (hz[i][j + 2] - hz[i - 1][j + 2]);
	      ey[i][j + 3] = ey[i][j + 3] - half * (hz[i][j + 3] - hz[i - 1][j + 3]);
	      ey[i][j + 4] = ey[i][j + 4] - half * (hz[i][j + 4] - hz[i - 1][j + 4]);
	      ey[i][j + 5] = ey[i][j + 5] - half * (hz[i][j + 5] - hz[i - 1][j + 5]);
	      ey[i][j + 6] = ey[i][j + 6] - half * (hz[i][j + 6] - hz[i - 1][j + 6]);
	      ey[i][j + 7] = ey[i][j + 7] - half * (hz[i][j + 7] - hz[i - 1][j + 7]);
	    }
	  for (; j < ny; j++)
	    ey[i][j] = ey[i][j] - half * (hz[i][j] - hz[i - 1][j]);
	}

      for (i = 0; i < nx; i++)
	{
	  j = 1;
	  for (; j + 7 < ny; j += 8)
	    {
	      ex[i][j]     = ex[i][j] - half * (hz[i][j] - hz[i][j - 1]);
	      ex[i][j + 1] = ex[i][j + 1] - half * (hz[i][j + 1] - hz[i][j]);
	      ex[i][j + 2] = ex[i][j + 2] - half * (hz[i][j + 2] - hz[i][j + 1]);
	      ex[i][j + 3] = ex[i][j + 3] - half * (hz[i][j + 3] - hz[i][j + 2]);
	      ex[i][j + 4] = ex[i][j + 4] - half * (hz[i][j + 4] - hz[i][j + 3]);
	      ex[i][j + 5] = ex[i][j + 5] - half * (hz[i][j + 5] - hz[i][j + 4]);
	      ex[i][j + 6] = ex[i][j + 6] - half * (hz[i][j + 6] - hz[i][j + 5]);
	      ex[i][j + 7] = ex[i][j + 7] - half * (hz[i][j + 7] - hz[i][j + 6]);
	    }
	  for (; j < ny; j++)
	    ex[i][j] = ex[i][j] - half * (hz[i][j] - hz[i][j - 1]);
	}

      for (i = 0; i < nx - 1; i++)
	{
	  j = 0;
	  for (; j + 7 < ny - 1; j += 8)
	    {
	      hz[i][j]     = hz[i][j] - seven * (ex[i][j + 1] - ex[i][j] + ey[i + 1][j] - ey[i][j]);
	      hz[i][j + 1] = hz[i][j + 1] - seven * (ex[i][j + 2] - ex[i][j + 1] + ey[i + 1][j + 1] - ey[i][j + 1]);
	      hz[i][j + 2] = hz[i][j + 2] - seven * (ex[i][j + 3] - ex[i][j + 2] + ey[i + 1][j + 2] - ey[i][j + 2]);
	      hz[i][j + 3] = hz[i][j + 3] - seven * (ex[i][j + 4] - ex[i][j + 3] + ey[i + 1][j + 3] - ey[i][j + 3]);
	      hz[i][j + 4] = hz[i][j + 4] - seven * (ex[i][j + 5] - ex[i][j + 4] + ey[i + 1][j + 4] - ey[i][j + 4]);
	      hz[i][j + 5] = hz[i][j + 5] - seven * (ex[i][j + 6] - ex[i][j + 5] + ey[i + 1][j + 5] - ey[i][j + 5]);
	      hz[i][j + 6] = hz[i][j + 6] - seven * (ex[i][j + 7] - ex[i][j + 6] + ey[i + 1][j + 6] - ey[i][j + 6]);
	      hz[i][j + 7] = hz[i][j + 7] - seven * (ex[i][j + 8] - ex[i][j + 7] + ey[i + 1][j + 7] - ey[i][j + 7]);
	    }
	  for (; j < ny - 1; j++)
	    hz[i][j] = hz[i][j] - seven * (ex[i][j + 1] - ex[i][j] + ey[i + 1][j] - ey[i][j]);
	}
    }

#pragma endscop
}

