static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#if defined(__riscv_vector)
  const int nj_local = nj;
  const int nk_local = nk;

  for (i = 0; i < ni; ++i) {
    DATA_TYPE *c_row = C[i];
    const DATA_TYPE *a_row = A[i];

    // Vectorized scalar multiplication of C[i][j] *= beta
    j = 0;
    while (j < nj_local) {
      size_t vl = __riscv_vsetvl_e64m1(static_cast<size_t>(nj_local - j));
      vfloat64m1_t vc = __riscv_vle64_v_f64m1(c_row + j, vl);
      vfloat64m1_t vb = __riscv_vfmv_v_f_f64m1(beta, vl);
      vc = __riscv_vfmul_vv_f64m1(vc, vb, vl);
      __riscv_vse64_v_f64m1(c_row + j, vc, vl);
      j += static_cast<int>(vl);
    }

    for (k = 0; k < nk_local; ++k) {
      const DATA_TYPE aik = a_row[k];
      const DATA_TYPE *b_col = B[k];

      j = 0;
      while (j < nj_local) {
        size_t vl = __riscv_vsetvl_e64m1(static_cast<size_t>(nj_local - j));
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(c_row + j, vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(b_col + j, vl);
        vfloat64m1_t va = __riscv_vfmv_v_f_f64m1(aik, vl);
        va = __riscv_vfmul_vv_f64m1(va, vb, vl);
        va = __riscv_vfmul_vv_f64m1(va, __riscv_vfmv_v_f_f64m1(alpha, vl), vl);
        vc = __riscv_vfadd_vv_f64m1(vc, va, vl);
        __riscv_vse64_v_f64m1(c_row + j, vc, vl);
        j += static_cast<int>(vl);
      }
    }
  }
#else
  for (i = 0; i < ni; i++) {
    for (j = 0; j < nj; j++)
      C[i][j] *= beta;
    for (k = 0; k < nk; k++) {
      for (j = 0; j < nj; j++)
        C[i][j] += alpha * A[i][k] * B[k][j];
    }
  }
#endif
}

