static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#pragma scop
  const int n1 = _PB_N - 1;

  for (t = 0; t < _PB_TSTEPS; t++)
    {
      for (i = 1; i < n1; i++)
	{
	  j = 1;
#if defined(__riscv_vector)
	  while (j < n1)
	    {
	      size_t vl = __riscv_vsetvl_e64m1(static_cast<size_t>(n1 - j));
	      vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
	      vfloat64m1_t vb = __riscv_vle64_v_f64m1(&A[i][j - 1], vl);
	      vfloat64m1_t vc = __riscv_vle64_v_f64m1(&A[i][j + 1], vl);
	      vfloat64m1_t vd = __riscv_vle64_v_f64m1(&A[1 + i][j], vl);
	      vfloat64m1_t ve = __riscv_vle64_v_f64m1(&A[i - 1][j], vl);

	      vfloat64m1_t vsum = __riscv_vfadd_vv_f64m1(va, vb, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vc, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vd, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, ve, vl);

	      vfloat64m1_t vout = __riscv_vfmul_vf_f64m1(vsum, SCALAR_VAL(0.2), vl);
	      __riscv_vse64_v_f64m1(&B[i][j], vout, vl);
	      j += static_cast<int>(vl);
	    }
#else
	  for (; j < n1; ++j)
	    B[i][j] = SCALAR_VAL(0.2) * (A[i][j] + A[i][j - 1] + A[i][1 + j] + A[1 + i][j] + A[i - 1][j]);
#endif
	}

      for (i = 1; i < n1; i++)
	{
	  j = 1;
#if defined(__riscv_vector)
	  while (j < n1)
	    {
	      size_t vl = __riscv_vsetvl_e64m1(static_cast<size_t>(n1 - j));
	      vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[i][j], vl);
	      vfloat64m1_t vbm1 = __riscv_vle64_v_f64m1(&B[i][j - 1], vl);
	      vfloat64m1_t vbm2 = __riscv_vle64_v_f64m1(&B[i][j + 1], vl);
	      vfloat64m1_t vbm3 = __riscv_vle64_v_f64m1(&B[1 + i][j], vl);
	      vfloat64m1_t vbm4 = __riscv_vle64_v_f64m1(&B[i - 1][j], vl);

	      vfloat64m1_t vsum = __riscv_vfadd_vv_f64m1(vb, vbm1, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vbm2, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vbm3, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vbm4, vl);

	      vfloat64m1_t vout = __riscv_vfmul_vf_f64m1(vsum, SCALAR_VAL(0.2), vl);
	      __riscv_vse64_v_f64m1(&A[i][j], vout, vl);
	      j += static_cast<int>(vl);
	    }
#else
	  for (; j < n1; ++j)
	    A[i][j] = SCALAR_VAL(0.2) * (B[i][j] + B[i][j - 1] + B[i][1 + j] + B[1 + i][j] + B[i - 1][j]);
#endif
	}
    }
#pragma endscop
}

