static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
  for (i = 0; i < _PB_M; i++)
  {
    const DATA_TYPE* Bi = B + i * _PB_N;
    const DATA_TYPE* Ai = A + i * _PB_M;
    DATA_TYPE* Ci = C + i * _PB_N;

    for (j = 0; j < _PB_N; j++ )
    {
      temp2 = 0.0;
      const DATA_TYPE bij = Bi[j];
      const DATA_TYPE aii = Ai[i];

      k = 0;
#if defined(__riscv_vector)
      for (; k + 4 <= i; k += 4)
      {
        const DATA_TYPE a0 = Ai[k];
        const DATA_TYPE a1 = Ai[k + 1];
        const DATA_TYPE a2 = Ai[k + 2];
        const DATA_TYPE a3 = Ai[k + 3];

        const DATA_TYPE b0 = Bi[k];
        const DATA_TYPE b1 = Bi[k + 1];
        const DATA_TYPE b2 = Bi[k + 2];
        const DATA_TYPE b3 = Bi[k + 3];

        const DATA_TYPE t0 = b0 * a0 + b1 * a1 + b2 * a2 + b3 * a3;
        temp2 += t0;

        Ci[k][j] += alpha * bij * a0;
        Ci[k + 1][j] += alpha * bij * a1;
        Ci[k + 2][j] += alpha * bij * a2;
        Ci[k + 3][j] += alpha * bij * a3;
      }
#endif
      for (; k < i; k++)
      {
        Ci[k][j] += alpha * bij * Ai[k];
        temp2 += Bi[k][j] * Ai[k];
      }
      Ci[j] = beta * Ci[j] + alpha * bij * aii + alpha * temp2;
    }
  }
#pragma endscop
}

